          version: '1.0.0',
          files: {
            'manifest.json': utf8.encode(
              jsonEncode({'id': 'from-catalog', 'name': 'Cat'}),
            ),
            'widget.js': utf8.encode('a'),
          },
        );
        final loader = UnpackedWidgetLoader(env: env, appsStore: store);
        await loader.install(
