      errors.add(
        WidgetPayloadError(
          'manifest_missing',
          root == null
              ? 'manifest.json not found in the picked folder — a widget is '
                    'a folder with manifest.json and widget.js at its root'
              : 'manifest.json not found in the picked folder (looked at '
