/// Widget integration tests for issue #866 — the apps panel (the launcher
/// grid) reflects reality: an agent-side manifest rename shows up without
/// reinstall or restart, and a manifest the agent broke renders a visible
/// error affordance while the panel stays usable.
library;

import 'package:fa/apps/apps_store.dart';
import 'package:fa/l10n/app_localizations.dart';
import 'package:fa/services/agent_service.dart';
import 'package:fa/services/flutter_session_manager.dart';
import 'package:fa/services/launcher_layout_store.dart';
import 'package:fa/ui/app_theme.dart';
import 'package:fa/ui/screens/app_launcher_screen.dart';
import 'package:flutter/material.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_test/flutter_test.dart';

StreamFunction _singleTextResponse(String text) {
  return (model, context, {cancelToken}) {
    final stream = AssistantMessageEventStream();
    final message = AssistantMessage(
      content: [TextContent(text: text)],
      api: model.api,
      provider: model.provider,
      model: model.id,
      usage: Usage.zero,
      stopReason: StopReason.stop,
      timestamp: DateTime.now(),
    );
    stream.push(DoneEvent(reason: StopReason.stop, message: message));
    stream.end();
    return stream;
  };
}

AgentService _fakeService(ExecutionEnv env) {
  return AgentService(
    agent: Agent(
      model: Model(
        id: 'test-model',
        api: 'test-api',
        provider: 'test',
        baseUrl: 'https://example.com',
        contextWindow: 100000,
        maxTokens: 4096,
      ),
      systemPrompt: 'You are Fa.',
      streamFunction: _singleTextResponse('ok'),
      toolRegistry: ToolRegistry(const []),
    ),
    env: env,
    sessionsRoot: '/sessions',
    config: AgentConfig(
      providerKind: 'test',
      modelId: 'test-model',
      baseUrl: 'https://example.com',
      apiKey: '',
    ),
  );
}

Future<AppsStore> _store(MemoryExecutionEnv env) async => AppsStore(
  env,
  readAsset: (path) async => throw StateError('no bundled assets here'),
  seedDemoIds: const [],
);

Future<FlutterSessionManager> _pumpLauncher(
  WidgetTester tester,
  MemoryExecutionEnv env,
) async {
  final manager = FlutterSessionManager(env: env, sessionsRoot: '/sessions');
  manager.addSession('test-session', _fakeService(env));
  tester.view.physicalSize = const Size(420, 900);
  tester.view.devicePixelRatio = 1.0;
  addTearDown(tester.view.reset);
  await tester.pumpWidget(
    MaterialApp(
      localizationsDelegates: AppLocalizations.localizationsDelegates,
      supportedLocales: AppLocalizations.supportedLocales,
      theme: buildFahTheme(),
      home: AppLauncherScreen(
        manager: manager,
        layoutStore: LauncherLayoutStore.inMemory(
          order: ['app:2048', 'app:broken'],
        ),
        appsStore: await _store(env),
      ),
    ),
  );
  await tester.pumpAndSettle();
  return manager;
}

Future<MemoryExecutionEnv> _seededEnv({required bool broken}) async {
  final env = MemoryExecutionEnv();
  await env.writeFile(
    'apps/2048/manifest.json',
    '{"id": "2048", "name": "2048", "description": "Tile game"}',
  );
  await env.writeFile('apps/2048/widget.js', '(function(){});');
  if (broken) {
    // A manifest an agent edit broke (issue #866): present, unparseable.
    await env.writeFile('apps/broken/manifest.json', '{"name": ');
    await env.writeFile('apps/broken/widget.js', '(function(){});');
  }
  return env;
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  testWidgets('AC1 — an agent rename appears without restart', (tester) async {
    final env = await _seededEnv(broken: false);
    final manager = await _pumpLauncher(tester, env);
    expect(find.text('2048'), findsWidgets);
    expect(find.text('2048 Renamed'), findsNothing);

    // The agent writes the rename through its regular file tools.
    await env.writeFile(
      'apps/2048/manifest.json',
      '{"id": "2048", "name": "2048 Renamed"}',
    );
    // The post-write hook: the launcher reloads on fsRevision bumps
    // (AgentService bumps it after every write/edit/bash tool call).
    manager.active!.service.fsRevision.value++;
    await tester.pumpAndSettle();
    expect(find.text('2048 Renamed'), findsWidgets);

    // Reopening the panel (a fresh surface) shows the new name too.
    await _pumpLauncher(tester, env);
    expect(find.text('2048 Renamed'), findsWidgets);
  });

  testWidgets('AC4 — broken manifest: flagged tile, usable panel', (
    tester,
  ) async {
    final env = await _seededEnv(broken: true);
    await _pumpLauncher(tester, env);
    // The broken app is visible (never silently dropped) under its folder
    // name, with the error badge on the tile.
    expect(find.text('broken'), findsWidgets);
    expect(find.text('!'), findsWidgets);

    // Tapping the broken tile surfaces the error instead of launching.
    await tester.tap(find.text('broken').first);
    await tester.pumpAndSettle();
    expect(find.text('App failed to load'), findsOneWidget);
    expect(find.textContaining('does not parse'), findsOneWidget);
    await tester.tap(find.text('Copy error'));
    await tester.pumpAndSettle();

    // The panel stays usable: the healthy neighbor still opens its menu.
    expect(find.text('2048'), findsWidgets);
  });
}

This is a great harness for the badge test. The `!` error badge is asserted via `find.text('!')`. The unpacked badge: a Tooltip with message `unpackedSourceBadgeTooltip` ("Loaded from a local folder (unpacked)") and an `Icons.folder_open` icon (size 8). To make an app "unpacked", I need the `.installed.json` record with origin 'unpacked' — I can write the meta file directly or use `AppsStore.installWidget(origin: 'unpacked')`. Let me check `installWidget` signature in apps_store.dart. And `failedSeeds`/`_appsById[id]?.error`.

So the test: an unpacked app whose manifest is later broken → both badges must be visible: `find.text('!')` findsOneWidget AND the folder_open icon findsOneWidget. With the current code, the folder badge (14x14) paints over the `!` badge (16x16)... in the WIDGET TREE both exist regardless of z-order. `find.text('!')` would find it either way — the overlap is a visual/paint issue. So a tree-presence test can't distinguish. To pin the FIX, I need to assert the two badges are in DIFFERENT corners. Options:

1. Golden test — pixel-level, catches overlap. The launcher golden harness exists with brokenManifest. Add an unpacked+broken tile golden. That's the strongest verification but requires generating a new PNG and eyeballing it (I can view via read image).

2. Widget test asserting geometry: find the Positioned widgets' offsets. I could find the badge containers by size (14x14 unpacked vs 16x16 error) via `find.byWidgetPredicate` and compare their global rects. E.g.:

```dart
final errorBadge = tester.getRect(find.byWidgetPredicate(
  (w) => w is Container && ... ));
```

Hmm, Containers with BoxDecoration shape circle, border... distinguishable by size: one is 14x14, the other 16x16. `tester.getRect` gives global coordinates. Assert the two rects' top-left corners differ (different corners) — i.e. the folder badge sits top-LEFT, the error badge top-RIGHT. That's a solid geometric regression test.

Actually simpler: after the fix, unpacked badge `Positioned(top: -3, left: -3)` — its rect.left < tile.left, while error badge rect.right > tile.right. Let me find the tile via find.text(label) ancestor... Getting the exact tile square: the InkWell child stack. Hmm, let me just find both badge containers by size and assert their rects don't overlap:

```dart
Rect badgeRect(double size) => tester.getRect(
  find.byWidgetPredicate((w) => w is Container && w.constraints == ...),
);
```

Container with width:14 — I can match via `find.byWidgetPredicate((widget) => widget is Container && (widget.constraints?.maxWidth == 14.0))` — but Container stores width in `constraints`? Container's `width` param ends up as `constraints: BoxConstraints.tightFor(width: 14)`. Actually Container keeps `width`/`height` in `constraints` as `BoxConstraints(minWidth: width, maxWidth: width, ...)`. Hmm, let me check: Container's `constraints` getter — when width != null, `BoxConstraints.tightFor(width: width)`. So `w.constraints?.maxWidth == 14.0`... but `constraints` is stored in `Container(constraints:)` merged. Container constructor stores `this.constraints` merged with width/height in `additionalConstraints`... Actually in Flutter, `Container` has an `additionalConstraints` computed from width/height only in `ConstrainedBox` created in build. The `Container.constraints` field holds what was passed to the constructor. width/height are separate fields (`this.width`). Container stores `final double? width;`. So predicate: `w is Container && w.constraints == null && w.width == 14.0`? Hmm, but `width` is a field on Container — yes, `Container.width` exists. OK:

```dart
Finder badge(double size) => find.byWidgetPredicate(
  (w) => w is Container && w.width == size && w.height == size,
);
```

14x14 → unpacked folder badge; 16x16 → error badge. Then:

```dart
final unpackedRect = tester.getRect(badge(14));
final errorRect = tester.getRect(badge(16));
// Different corners: the folder badge hugs the top-left, the error badge the top-right.
expect(unpackedRect.left, lessThan(errorRect.left));
expect(errorRect.right, greaterThan(unpackedRect.right));
expect(unpackedRect.overlaps(errorRect), isFalse);
```

Good, that pins the corner fix without goldens. But hold on — where to put this test? `test/apps/app_launcher_reality_test.dart` is the #866 file... adding gh-1616 tests there is fine? Or a new test file `test/apps/launcher_badges_test.dart`? There's a golden_guard mapping and possibly other guard tests that check new test files... Let me check if there's a convention. Simpler: extend `app_launcher_reality_test.dart` — it's exactly about launcher tile reality (broken manifest + badge). Add a test 'gh-1616 — unpacked badge and error badge share no corner'.

To seed an unpacked app: write the app files, then write the `.installed.json` meta record with origin 'unpacked'. Let me read apps_store installWidget + the meta file format.

