    final errors = <WidgetPayloadError>[];
    final warnings = <WidgetPayloadWarning>[];

    // ── path normalization + root clamping ─────────────────────────────
    var files = normalizePaths(pickedFiles, errors);
    if (errors.isNotEmpty) {
