          'entry_missing',
          'widget.js not found in the picked folder — the entry file the '
              'engine runs is missing',
        ),
      );
    } else if (entryBytes.isEmpty) {
      errors.add(const WidgetPayloadError('entry_empty', 'widget.js is empty'));
