      'name': 'FA Agents',
      'version': '0.3.0',
      'network': network,
    }),
  ),
  'fa-agents/widget.js': utf8.encode('jsr.render(null);'),
};

Future<(MemoryExecutionEnv, FlutterSessionManager)> _pump(
  WidgetTester tester,
  _StubPicker picker, {
  AppsStore? appsStore,
}) async {
  TestWidgetsFlutterBinding.ensureInitialized();
  final env = MemoryExecutionEnv();
  final manager = FlutterSessionManager(env: env, sessionsRoot: '/sessions');
  manager.addSession('test-session', _fakeService(env));
  await tester.pumpWidget(
    MaterialApp(
      theme: buildFahTheme(),
      home: Scaffold(
        body: Builder(
          builder: (context) => TextButton(
            onPressed: () => loadUnpackedWidget(
              context,
              manager: manager,
              appsStore: appsStore,
              picker: picker,
            ),
            child: const Text('load'),
          ),
        ),
      ),
    ),
  );
  return (env, manager);
}

void main() {
  testWidgets('AC1: valid folder → confirm → installed, grid refreshes', (
    tester,
