  // `uses-material-design: true` places MaterialIcons under fonts/.
  final icons = FontLoader('MaterialIcons')
    ..addFont(rootBundle.load('fonts/MaterialIcons-Regular.otf'));
  await inter.load();
  await mono.load();
  await icons.load();
  _fontsLoaded = true;
}

