    expect(find.text('2048'), findsWidgets);
    expect(find.text('2048 Renamed'), findsNothing);

    // The agent writes the rename through its regular file tools.
    await env.writeFile(
      'apps/2048/manifest.json',
      '{"id": "2048", "name": "2048 Renamed"}',
