// `unpacked_load_confirm_replace_agent.png` (gh-1616 rework): pixel-diff
// it against the catalog-source replace golden. Expected: identical
// size, and the differing region confined to the dialog's replace-note
// text block (a shorter source phrase on the same wrapped rows — no
// overflow outside the dialog, no layout blowup).
import 'dart:io';

import 'package:image/image.dart' as img;

void main() {
  final a = img.decodePng(
    File('test/golden/goldens/unpacked_load_confirm_replace.png').readAsBytesSync(),
  )!;
  final b = img.decodePng(
    File('test/golden/goldens/unpacked_load_confirm_replace_agent.png')
        .readAsBytesSync(),
  )!;
  stdout.writeln('catalog: ${a.width}x${a.height}  agent: ${b.width}x${b.height}');
  if (a.width != b.width || a.height != b.height) {
    stdout.writeln('FAIL: size mismatch');
    exitCode = 1;
    return;
  }
  int minX = a.width, minY = a.height, maxX = -1, maxY = -1, diff = 0;
  for (var y = 0; y < a.height; y++) {
    for (var x = 0; x < a.width; x++) {
      final pa = a.getPixel(x, y);
      final pb = b.getPixel(x, y);
      if (pa.r != pb.r || pa.g != pb.g || pa.b != pb.b) {
        diff++;
        if (x < minX) minX = x;
        if (y < minY) minY = y;
        if (x > maxX) maxX = x;
        if (y > maxY) maxY = y;
      }
    }
  }
  stdout.writeln('differing pixels: $diff');
  stdout.writeln('diff bounding box: x=$minX..$maxX y=$minY..$maxY');
}
